<script>
import { gsap } from 'gsap'

export default {
  name: 'AgencyLogo',
  props: {
    color: {
      type: String,
      default: '#FFFFFF'
    }
  },
  data() {
    return {
      currentFrame: 0,
      timeline: null,
      floatTimeline: null,
      frillsTimeline: null
    }
  },
  mounted() {
    // Start the continuous floating animation
    this.floatTimeline = gsap.timeline({ repeat: -1, yoyo: true })
      .to(this.$el, { y: -10, duration: 1, ease: "power1.inOut" })

    // Start the continuous frills scrolling animation - loop back early for seamless transition
    this.$nextTick(() => {
      if (this.$refs.frills) {
        this.frillsTimeline = gsap.timeline({ repeat: -1 })
          .fromTo(this.$refs.frills,
            { x: 0 },
            { x: -417, duration: 22.2, ease: "none" }
          )
      }
    })
  },
  computed: {
    frame() {
      return Math.round(this.currentFrame)
    }
  },
  methods: {
    startAnimation() {
      // Kill any existing timeline
      if (this.timeline) {
        this.timeline.kill()
      }

      // Create new timeline that cycles through frames once
      // Faster at the beginning (0→1→2), slower around closing (3→4)
      this.timeline = gsap.timeline()
        .to(this, { currentFrame: 1, duration: 0.014 })  // Fast
        .to(this, { currentFrame: 2, duration: 0.014 })  // Fast
        .to(this, { currentFrame: 3, duration: 0.0225 }) // Medium
        .to(this, { currentFrame: 4, duration: 0.034 })  // Slow (eyes closing)
        .to(this, { currentFrame: 3, duration: 0.034 })  // Slow (eyes opening)
        .to(this, { currentFrame: 2, duration: 0.0225 }) // Medium
        .to(this, { currentFrame: 1, duration: 0.014 })  // Fast
        .to(this, { currentFrame: 0, duration: 0.014 })  // Fast
    },
    stopAnimation() {
      if (this.timeline) {
        this.timeline.kill()
      }
      // Reset to frame 0
      gsap.to(this, { currentFrame: 0, duration: 0.1 })
    }
  },
  beforeDestroy() {
    if (this.timeline) {
      this.timeline.kill()
    }
    if (this.floatTimeline) {
      this.floatTimeline.kill()
    }
    if (this.frillsTimeline) {
      this.frillsTimeline.kill()
    }
  }
}
</script>

